using System;using System.Drawing;using System.Windows.Forms;
partial class MainWindow {
 Label downSpeed,upSpeed,serverHost,latency,dns,routing;
 Label Fact(TableLayoutPanel grid,string name,int column,int row,int span=1){var title=Label(name,8,FontStyle.Bold,Palette.Muted);title.Dock=DockStyle.Fill;grid.Controls.Add(title,column,row);var value=Label("Unavailable",9,FontStyle.Bold,Palette.Text);value.Dock=DockStyle.Fill;value.TextAlign=ContentAlignment.MiddleLeft;grid.Controls.Add(value,column,row+1);if(span>1){grid.SetColumnSpan(title,span);grid.SetColumnSpan(value,span);}return value;}
 void InitializeNetworkFields(TableLayoutPanel grid){downSpeed=Fact(grid,"DOWNLOAD SPEED",0,4);upSpeed=Fact(grid,"UPLOAD SPEED",1,4);serverHost=Fact(grid,"SERVER HOST / ADDRESS",2,4,2);latency=Fact(grid,"SERVER PING",0,6);routing=Fact(grid,"TUNNEL ROUTES",1,6,2);dns=Fact(grid,"ADAPTER DNS",3,6);detailTips.SetToolTip(latency,"ICMP round trip to the VPN server. A blocked ping does not mean the VPN has failed.");detailTips.SetToolTip(routing,"Routes configured on the matched VPN adapter, separated by IP family. This is not a leak test or a guarantee about effective route priority.");}
 void RefreshNetworkFields(){if(downSpeed==null)return;var snapshot=session==null?new ConnectionSnapshot():session.Metrics.Snapshot();downSpeed.Text=ConnectionMetrics.Speed(snapshot.DownloadSpeed);upSpeed.Text=ConnectionMetrics.Speed(snapshot.UploadSpeed);var facts=session==null?new NetworkFacts():session.Facts();serverHost.Text=facts.ServerHost==null?facts.ServerAddress??"Unavailable":facts.ServerHost+(String.IsNullOrEmpty(facts.ServerAddress)||facts.ServerAddress==facts.ServerHost?"":" ("+facts.ServerAddress+")");detailTips.SetToolTip(serverHost,"Configured server: "+(facts.ServerHost??"Unavailable")+Environment.NewLine+"Active server address: "+(facts.ServerAddress??"Unavailable"));latency.Text=facts.Latency??"Unavailable";routing.Text=facts.Routing??"Unavailable";dns.Text=String.IsNullOrEmpty(facts.Dns)?"Unavailable":facts.Dns;detailTips.SetToolTip(dns,"DNS configured on the matched VPN adapter: "+dns.Text+". Windows DNS policies may override adapter settings.");}
}

